EXPECTED = {"torso": 1, "vest": 10, "shoes": 52, "tshirt": 34}

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 WardrobeCatalogImport/1.0"})
    with urllib.request.urlopen(req, timeout=45) as r:
        return r.read()

def jpeg_data_url(raw):
    with Image.open(io.BytesIO(raw)) as image:
        if image.mode not in ("RGB", "L"):
            background = Image.new("RGB", image.size, "white")
            if "A" in image.getbands():
                background.paste(image, mask=image.getchannel("A"))
            else:
                background.paste(image.convert("RGB"))
            image = background
        else:
            image = image.convert("RGB")
        image.thumbnail((700, 700), Image.Resampling.LANCZOS)
        out = io.BytesIO()
        image.save(out, format="JPEG", quality=80, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(out.getvalue()).decode("ascii")

result = {"torso": [], "vest": [], "shoes": [], "tshirt": [], "orders": SOURCE["orders"]}
for category in ("torso", "vest", "shoes", "tshirt"):
    rows = SOURCE[category]
    if len(rows) != EXPECTED[category]:
        raise SystemExit(f"Unexpected {category} count: {len(rows)}")
    for i, item in enumerate(rows, 1):
        print(f"{category}: {i}/{len(rows)} - ID {item['id']}", flush=True)
        raw = fetch(item["url"])
        result[category].append({
            "id": int(item["id"]) if item["id"].isdigit() else item["id"],
            "description": item["description"],
            "image": jpeg_data_url(raw),
        })

Path("catalog-extra.js").write_text(
    "window.WARDROBE_EXTRA_CATALOG = " +
    json.dumps(result, ensure_ascii=False, separators=(",", ":")) +
    ";\n",
    encoding="utf-8",
)
print("catalog-extra.js written", flush=True)
